import re

# 1. Find the line range for the function
nodes = ctx.list_nodes("function")
func_node = next((n for n in nodes if n["name"] == args["function_name"] and n["path"] == args["file_path"]), None)
if not func_node:
    return {"error": "Function not found or path mismatch."}

start_line = func_node["line"]
end_line = func_node["end"]

# 2. Use git_blame to get blame info for the range
blame_data = ctx.git_blame(args["file_path"], start_line, end_line)

# 3. Process blame data to find the most recent change for the whole function
# Since blame gives line-by-line, we'll aggregate the latest info found.
# We assume the last entry in the blame list (if sorted by date, which it isn't guaranteed to be) or just take the first one as representative if we can't sort reliably.
# Given the constraint, we'll find the max date from the available entries.

latest_commit = None
latest_date = "0000-00-00"

for entry in blame_data:
    # ISO dates sort correctly as strings
    if entry["date"] > latest_date:
        latest_date = entry["date"]
        latest_commit = entry

if latest_commit:
    return {"last_changed_date": latest_commit["date"], "author": latest_commit["author"]}
else:
    return {"error": "Could not retrieve blame information for the specified range."}

